<?php
session_start();require_once __DIR__.'/config/database.php';$errors=[];$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){$login=trim($_POST['login']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm']??'';if(!$login||!$email)$errors[]='Укажите логин и email.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Email указан неверно.';if(strlen($password)<6)$errors[]='Новый пароль должен содержать минимум 6 символов.';if($password!==$confirm)$errors[]='Пароли не совпадают.';if(!$errors){$q=$pdo->prepare("SELECT id FROM users WHERE login=? AND email=? AND status='active' LIMIT 1");$q->execute([$login,$email]);$uid=$q->fetchColumn();if(!$uid)$errors[]='Пользователь с таким логином и email не найден.';else{$pdo->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$uid]);$pdo->prepare('INSERT INTO password_reset_log(user_id,ip_address) VALUES(?,?)')->execute([$uid,$_SERVER['REMOTE_ADDR']??'']);$_SESSION['register_success']='Пароль восстановлен. Теперь войдите с новым паролем.';header('Location:index.php');exit;}}}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Восстановление доступа</title><link rel="stylesheet" href="assets/css/style.css"><script defer src="assets/js/script.js"></script></head><body class="login-page"><div class="login-box"><div class="login-logo"><span class="brand-mark">🔐</span></div><h1>Восстановление доступа</h1><div class="sub">Подтвердите логин и email, затем задайте новый пароль</div><?php if($errors):?><div class="notice error"><?php foreach($errors as $e):?><div>• <?=htmlspecialchars($e)?></div><?php endforeach;?></div><?php endif;?><form method="post"><div class="form-group"><label>Логин</label><input name="login" required value="<?=htmlspecialchars($_POST['login']??'')?>"></div><div class="form-group"><label>Email</label><input type="email" name="email" required value="<?=htmlspecialchars($_POST['email']??'')?>"></div><div class="form-group"><label>Новый пароль</label><input type="password" name="password" minlength="6" required oninput="updatePasswordStrength(this.value)"><div class="password-strength"><i id="passwordStrength"></i></div></div><div class="form-group"><label>Повторите пароль</label><input type="password" name="confirm" minlength="6" required></div><button class="btn">Сменить пароль</button></form><div class="auth-switch"><a href="index.php">← Вернуться ко входу</a></div><div class="demo">Для локальной учебной версии письмо не отправляется: система проверяет совпадение логина и email из профиля.</div></div></body></html>
